#!/usr/bin/env python3
"""Generate the static GStreamer plugin registration source for a sample.

Usage: generate-static-plugins.py OUTPUT PLUGIN [PLUGIN...]

GStreamer static plugins have to be declared and registered manually from C.
Keeping the list in Meson and generating this file avoids duplicating the list
in every sample's C source.
"""

import sys


def main():
    if len(sys.argv) < 3:
        sys.stderr.write(__doc__)
        return 2

    output = sys.argv[1]
    plugins = sys.argv[2:]

    lines = [
        "/* Generated by generate-static-plugins.py. Do not edit. */",
        "#include <gst/gst.h>",
        "",
    ]
    for plugin in plugins:
        lines.append(f"GST_PLUGIN_STATIC_DECLARE ({plugin});")
    lines += ["", "void", "gst_wasm_register_static_plugins (void)", "{"]
    for plugin in plugins:
        lines.append(f"  GST_PLUGIN_STATIC_REGISTER ({plugin});")
    lines += ["}", ""]

    with open(output, "w", encoding="utf-8") as f:
        f.write("\n".join(lines))
    return 0


if __name__ == "__main__":
    sys.exit(main())
